<p class="eyebrow">Account settings</p><h1>Profile</h1><div class="card form-card"><form method="post" action="<?= e(route('dashboard.profile.update')) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><label class="field">First name<input name="first_name" required value="<?= e($user['first_name']) ?>"></label><label class="field">Last name<input name="last_name" required value="<?= e($user['last_name']) ?>"></label></div><label class="field">Phone<input name="phone" autocomplete="tel" value="<?= e($user['phone']??'') ?>"></label><label class="field">Interface language<select name="language"><?php foreach($languages as $language): ?><option value="<?= e($language['code']) ?>"<?= $language['code']===country()->languageCode?' selected':'' ?>><?= e($language['native_name']) ?></option><?php endforeach; ?></select></label><div class="readonly-row"><span>Investment region</span><strong><?= e(country()->name()) ?> · <?= e(country()->currencyCode()) ?></strong></div><p class="help">Your language preference changes the interface only. Your investment region is controlled by platform rules and can only be changed by an administrator.</p><button class="button" type="submit">Save profile</button></form></div>
